parameters.jsCode:
const items = $input.all();
let nameVal = '';
let serviceVal = '';
let llmOutput = '';
let fullText = '';

for (let item of items) {
    const json = item.json || {};
    const output = json.output || json;

    if (!llmOutput) {
        llmOutput = json.text || json.output || json.response || (typeof output === 'string' ? output : '') || '';
    }

    if (!nameVal) nameVal = output.name || json.name || output.customer_name || json.customer_name || '';
    if (!serviceVal) serviceVal = output.requested_service || json.requested_service || output.services || json.services || '';

    const textToCheck = json.chatInput || json.message || json.text || JSON.stringify(json);
    if (textToCheck) fullText += " " + textToCheck;
}

if (!nameVal && fullText) {
    const nameMatch = fullText.match(/my name is\s+([a-zA-Z]+)/i);
    if (nameMatch) nameVal = nameMatch[1];
}

if (!serviceVal && fullText) {
    if (fullText.toLowerCase().includes('cyber defense platform')) {
        serviceVal = 'Cyber Defense Platform';
    } else if (fullText.toLowerCase().includes('cyber security')) {
        serviceVal = 'Cyber Security Service';
    } else if (fullText.toLowerCase().includes('software solution')) {
        serviceVal = 'Software Solution';
    }
}

let finalMessage = '';

if (llmOutput && llmOutput.length > 10 && !llmOutput.includes('[Customer Name]')) {
    finalMessage = llmOutput;
} else {
    const userName = nameVal ? ` ${nameVal}` : '';
    const service = serviceVal ? ` for your ${serviceVal}` : '';
    finalMessage = `Hi${userName}! We have received your inquiry${service}. Our team will get in touch with you shortly.`;
}

return [{ 
    json: { 
        assistant_message: finalMessage,
        customer_name: nameVal,
        requested_service: serviceVal,
        success: true
    } 
}];

