parameters.jsCode:
const input = $input.first()?.json || {};

let normJson = {};
try { normJson = $('Normalize Lead Details').first()?.json || {}; } catch (e) {}

let prepJson = {};
try { prepJson = $('Prepare Lead').first()?.json || {}; } catch (e) {}

let triggerJson = {};
try { triggerJson = $('When Executed by Another Workflow').first()?.json || {}; } catch (e) {}

let msg = 
  input.assistant_message || 
  input.response ||
  input.output || 
  input.final_response || 
  input.response_message ||
  prepJson.assistant_message ||
  normJson.assistant_message ||
  input.message;

if (!msg || typeof msg !== 'string' || msg.trim() === '') {
  const name = input.name || prepJson.name || normJson.name || triggerJson.customer_name || '';
  const svc = input.requested_service || prepJson.requested_service || normJson.requested_service || '';
  const nameStr = name ? (' ' + name) : '';
  const svcStr = svc ? (' for ' + svc) : '';
  msg = 'Hi' + nameStr + '! We have received your inquiry' + svcStr + '. Our cybersecurity team has logged your request and will follow up with you shortly.';
}

const customerName = input.name || prepJson.name || normJson.name || triggerJson.customer_name || '';
const customerEmail = input.email || prepJson.email || normJson.email || triggerJson.email || '';
const customerPhone = input.phone || prepJson.phone || normJson.phone || triggerJson.phone || '';
const requestedService = input.requested_service || prepJson.requested_service || normJson.requested_service || '';

return [{
  json: {
    ...prepJson,
    ...normJson,
    ...input,
    assistant_message: msg,
    output: msg,
    final_response: msg,
    response_message: msg,
    status: 'success',
    execution_result: 'success',
    execution_status: 'completed',
    response_status: 'completed',
    selected_agent: 'Lead Capture Agent',
    agent_name: 'Lead Capture Agent',
    lead_id: input.lead_id || prepJson.lead_id || ('LEAD-' + Date.now()),
    customer_name: customerName,
    name: customerName,
    email: customerEmail,
    phone: customerPhone,
    requested_service: requestedService,
    completed_at: new Date().toISOString()
  }
}];
